codeExample.bad:
/* Parallax scroll effect with no way to disable it */
.parallax-section {
  background-attachment: fixed;
  transition: transform 0.3s ease-out;
}
.parallax-section.scrolled {
  transform: translateY(-50px) scale(1.1);
}

codeExample.good:
/* The same effect, disabled automatically when the user has requested
   reduced motion at the OS or browser level */
@media (prefers-reduced-motion: no-preference) {
  .parallax-section {
    background-attachment: fixed;
    transition: transform 0.3s ease-out;
  }
  .parallax-section.scrolled {
    transform: translateY(-50px) scale(1.1);
  }
}
/* With reduced motion requested, the section keeps its static
   background position and no transform is applied */
